import "server-only";

/** school_0001, school_0002 ... (prefix configurable so tests use test_school_). */
export function schoolDatabaseName(prefix: string, n: number): string {
  if (!Number.isInteger(n) || n < 1) throw new Error("Invalid school number");
  return `${prefix}${String(n).padStart(4, "0")}`;
}

export function schoolRoleName(databaseName: string): string {
  return `${databaseName}_app`;
}

const IDENT = /^[a-z][a-z0-9_]{0,62}$/;

/** Defence in depth: names are generated by us, but never interpolate anything unexpected. */
export function assertSafeIdentifier(name: string): string {
  if (!IDENT.test(name)) throw new Error(`Unsafe SQL identifier: ${name}`);
  return name;
}

const SLUG = /^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$/;

export function isValidSlug(slug: string): boolean {
  return SLUG.test(slug);
}
